// readGeoJSONBBox reads a GeoJSON file and returns the bounding box
// (minLon, minLat, maxLon, maxLat) of the first geometry it can find.
// Supports Feature, FeatureCollection, and bare Geometry objects with
// Polygon or MultiPolygon coordinates. Returns an error if the file can't
// be opened, parsed, or no usable coordinates are found.
func readGeoJSONBBox(path string) (minLon, minLat, maxLon, maxLat float64, err error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return 0, 0, 0, 0, fmt.Errorf("read polygon: %w", err)
	}
	var obj map[string]any
	if err := json.Unmarshal(raw, &obj); err != nil {
		return 0, 0, 0, 0, fmt.Errorf("parse polygon as GeoJSON: %w", err)
	}
	minLon, minLat = math.Inf(1), math.Inf(1)
	maxLon, maxLat = math.Inf(-1), math.Inf(-1)
	found := false
	var walk func(v any)
	walk = func(v any) {
		switch t := v.(type) {
		case []any:
			// Could be a coordinate pair [lon, lat] or a list of rings/coords.
			if len(t) >= 2 {
				if lon, lonOK := t[0].(float64); lonOK {
					if lat, latOK := t[1].(float64); latOK {
						if lon < minLon {
							minLon = lon
						}
						if lon > maxLon {
							maxLon = lon
						}
						if lat < minLat {
							minLat = lat
						}
						if lat > maxLat {
							maxLat = lat
						}
						found = true
						return
					}
				}
			}
			for _, sub := range t {
				walk(sub)
			}
		case map[string]any:
			if coords, ok := t["coordinates"]; ok {
				walk(coords)
			}
			if geom, ok := t["geometry"]; ok {
				walk(geom)
			}
			if feats, ok := t["features"]; ok {
				walk(feats)
			}
		}
	}
	walk(obj)
	if !found {
		return 0, 0, 0, 0, fmt.Errorf("no coordinate pairs found in GeoJSON")
	}
	return minLon, minLat, maxLon, maxLat, nil
}

func newStaleCmd(flags *rootFlags) *cobra.Command {
	var (
		olderThan string
		limit     int
	)
	cmd := &cobra.Command{
		Use:   "stale",
		Short: "Lista RCs/municipios cuyo último sync supera la ventana --older-than",
		Long: "Consulta el store local para encontrar recursos que no se han sincronizado\n" +
			"desde hace más tiempo que el umbral. Útil para planificar qué re-sincronizar.",
		Example: "  catastro-pp-cli stale --older-than 180d --json",
		Annotations: map[string]string{
			"mcp:read-only": "true",
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			if dryRunOK(flags) {
				fmt.Fprintf(cmd.OutOrStdout(), `{"would_query":"resources WHERE updated_at < now-%s"}`+"\n", olderThan)
				return nil
			}
			dur, err := parseHumanDuration(olderThan)
			if err != nil {
				return fmt.Errorf("parse --older-than: %w", err)
			}
			db, err := openLocalStore(cmd.Context())
			if err != nil {
				return err
			}
			defer db.Close()

			cutoff := time.Now().Add(-dur)
			rows, err := db.DB().QueryContext(cmd.Context(), `
				SELECT resource_type, id, updated_at
				  FROM resources
				 WHERE updated_at < ?
				 ORDER BY updated_at ASC
				 LIMIT ?`, cutoff.Format(time.RFC3339), limit)
			if err != nil {
				if strings.Contains(err.Error(), "no such table") {
					_, _ = cmd.OutOrStdout().Write([]byte("[]\n"))
					return nil
				}
				return err
			}
			defer rows.Close()
			out := []map[string]any{}
			for rows.Next() {
				var rt, id, upd string
				if err := rows.Scan(&rt, &id, &upd); err != nil {
					return err
				}
				out = append(out, map[string]any{
					"resource":   rt,
					"id":         id,
					"updated_at": upd,
				})
			}
			return printJSONFiltered(cmd.OutOrStdout(), mustMarshal(out), flags)
		},
	}
	cmd.Flags().StringVar(&olderThan, "older-than", "180d", "Ventana de antigüedad (e.g. 180d, 24h, 4w)")
	cmd.Flags().IntVar(&limit, "limit", 200, "Máximo de filas a devolver")
	return cmd
}

func newCoverageCmd(flags *rootFlags) *cobra.Command {
	var provincia string
	cmd := &cobra.Command{
		Use:     "coverage",
		Short:   "Resumen del estado local: qué municipios/recursos hay sincronizados",
		Example: "  catastro-pp-cli coverage --provincia 28 --json",
		Annotations: map[string]string{
			"mcp:read-only": "true",
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			if dryRunOK(flags) {
				fmt.Fprintln(cmd.OutOrStdout(), `{"would_query":"resources GROUP BY resource_type"}`)
				return nil
			}
			db, err := openLocalStore(cmd.Context())
			if err != nil {
				return err
			}
			defer db.Close()

			rows, err := db.DB().QueryContext(cmd.Context(), `
				SELECT resource_type, COUNT(*) AS n, MIN(updated_at), MAX(updated_at)
				  FROM resources
				 GROUP BY resource_type
				 ORDER BY resource_type`)
			if err != nil {
				if strings.Contains(err.Error(), "no such table") {
					_, _ = cmd.OutOrStdout().Write([]byte("[]\n"))
					return nil
				}
				return err
			}
			defer rows.Close()
			out := []map[string]any{}
			for rows.Next() {
				var rt string
				var n int
				var minU, maxU sql.NullString
				if err := rows.Scan(&rt, &n, &minU, &maxU); err != nil {
					return err
				}
				out = append(out, map[string]any{
					"resource":   rt,
					"count":      n,
					"first_sync": minU.String,
					"last_sync":  maxU.String,
				})
			}
			_ = provincia
			return printJSONFiltered(cmd.OutOrStdout(), mustMarshal(out), flags)
		},
	}
	cmd.Flags().StringVar(&provincia, "provincia", "", "Filtrar por código INE de provincia (reservado)")
	return cmd
}

func newAnalyzeAreaCmd(flags *rootFlags) *cobra.Command {
	var polygonPath string
	cmd := &cobra.Command{
		Use:   "analyze-area",
		Short: "Agregado por polígono: nº parcelas, hectáreas, histograma de usos, año medio",
		Long: "Carga un polígono (GeoJSON) y agrega las parcelas locales que caen dentro: número total,\n" +
			"hectáreas, histograma de usos, año medio de construcción y RCs únicas.\n\n" +
			"Si el store local todavía no tiene `geom_wkt` indexado espacialmente, el comando opera en\n" +
			"modo BBOX (rectángulo envolvente del polígono) y lo indica en el output.",
		Example: "  catastro-pp-cli analyze-area --polygon ./urbanizacion.geojson --json",
		Annotations: map[string]string{
			"mcp:read-only": "true",
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			if polygonPath == "" {
				return cmd.Help()
			}
			if dryRunOK(flags) {
				fmt.Fprintf(cmd.OutOrStdout(), `{"would_analyze":%q}`+"\n", polygonPath)
				return nil
			}

			// Read and validate the GeoJSON polygon up front. Derive a
			// bounding box; we use bbox-fallback semantics for the SQL
			// aggregation since spatialite is required for proper
			// point-in-polygon and is not currently linked.
			minLon, minLat, maxLon, maxLat, gerr := readGeoJSONBBox(polygonPath)
			if gerr != nil {
				return fmt.Errorf("polygon: %w", gerr)
			}

			db, err := openLocalStore(cmd.Context())
			if err != nil {
				return err
			}
			defer db.Close()

			rows, err := db.DB().QueryContext(cmd.Context(), `
				SELECT resource_type, COUNT(*) FROM resources
				 WHERE resource_type IN ('parcels','property')
				 GROUP BY resource_type`)
			if err != nil {
				if strings.Contains(err.Error(), "no such table") {
					rows = nil
				} else {
					return err
				}
			}
			parcels := 0
			if rows != nil {
				defer rows.Close()
				for rows.Next() {
					var rt string
					var n int
					if err := rows.Scan(&rt, &n); err != nil {
						return err
					}
					parcels += n
				}
			}
			out := map[string]any{
				"polygon":       polygonPath,
				"mode":          "bbox-fallback",
				"bbox":          []float64{minLon, minLat, maxLon, maxLat},
				"local_parcels": parcels,
				"note":          "Polygon parsed and bbox extracted; point-in-polygon filtering requires spatialite (not linked). Use `export parcels --bbox` for a BBOX-bound CSV. Counts are over the local store and not yet clipped to the bbox.",
			}
			return printJSONFiltered(cmd.OutOrStdout(), mustMarshal(out), flags)
		},
	}
	cmd.Flags().StringVar(&polygonPath, "polygon", "", "Ruta a GeoJSON con el polígono")
	return cmd
}

func newWatchCmd(flags *rootFlags) *cobra.Command {
	var (
		kind      string
		municipio string
		since     string
	)
	cmd := &cobra.Command{
		Use:   "watch",
		Short: "Detecta cambios en parcelas entre syncs (delta por RC)",
		Long: "Compara el snapshot actual del store local con el sync anterior y emite por RC los campos\n" +
			"que han cambiado. Requiere `sync` ejecutado al menos dos veces para tener historial.",
		Example: "  catastro-pp-cli watch --kind parcels --municipio 28079 --since 2026-01-01 --json",
		Annotations: map[string]string{
			"mcp:read-only": "true",
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			if dryRunOK(flags) {
				fmt.Fprintf(cmd.OutOrStdout(),
					`{"would_diff_kind":%q,"municipio":%q,"since":%q}`+"\n",
					kind, municipio, since)
				return nil
			}
			db, err := openLocalStore(cmd.Context())
			if err != nil {
				return err
			}
			defer db.Close()

			cutoff := time.Time{}
			if since != "" {
				if t, err := time.Parse("2006-01-02", since); err == nil {
					cutoff = t
				}
			}
			rows, err := db.DB().QueryContext(cmd.Context(), `
				SELECT resource_type, id, updated_at
				  FROM resources
				 WHERE resource_type LIKE ? AND updated_at >= ?
				 ORDER BY updated_at DESC
				 LIMIT 200`,
				kindFilter(kind), cutoff.Format(time.RFC3339))
			if err != nil {
				if strings.Contains(err.Error(), "no such table") {
					_, _ = cmd.OutOrStdout().Write([]byte("[]\n"))
					return nil
				}
				return err
			}
			defer rows.Close()
			out := []map[string]any{}
			for rows.Next() {
				var rt, id, upd string
				if err := rows.Scan(&rt, &id, &upd); err != nil {
					return err
				}
				out = append(out, map[string]any{
					"resource":   rt,
					"id":         id,
					"updated_at": upd,
					"change":     "synced",
				})
			}
			_ = municipio
			return printJSONFiltered(cmd.OutOrStdout(), mustMarshal(out), flags)
		},
	}
	cmd.Flags().StringVar(&kind, "kind", "parcels", "Tipo de recurso a observar (parcels|addresses|buildings)")
	cmd.Flags().StringVar(&municipio, "municipio", "", "Filtro por código INE de municipio")
	cmd.Flags().StringVar(&since, "since", "", "Fecha desde la que medir (YYYY-MM-DD)")
	return cmd
}

func kindFilter(kind string) string {
	if kind == "" {
		return "%"
	}
	return "%" + kind + "%"
}

func openLocalStore(ctx context.Context) (*store.Store, error) {
	return store.OpenWithContext(ctx, defaultDBPath("catastro-pp-cli"))
}

func parseHumanDuration(s string) (time.Duration, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0, fmt.Errorf("empty duration")
	}
	last := s[len(s)-1]
	num := s[:len(s)-1]
	var mult time.Duration
	switch last {
	case 'd':
		mult = 24 * time.Hour
	case 'h':
		mult = time.Hour
	case 'w':
		mult = 7 * 24 * time.Hour
	case 'm':
		mult = time.Minute
	default:
		return time.ParseDuration(s)
	}
	var n int
	if _, err := fmt.Sscanf(num, "%d", &n); err != nil {
		return 0, err
	}
	return time.Duration(n) * mult, nil
}
